@@ -0,0 +1,30 @@
+// Sites: each kitchen has its own locations, and so its own batches. Items,
+// suppliers, recipes and dishes are shared (docs/DATA.md).
+import { AppError } from "../errors.js";
+
+/** The site of a request that names none. */
+export const DEFAULT_SITE = "main";
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site a location belongs to (locations without one are in the default site). */
+export function siteOfLocation(store, locationId) {
+  const loc = store.data.locations.find((l) => l.id === locationId);
+  return loc?.site ?? DEFAULT_SITE;
+}
+
+/** True when `locationId` is a location of `site`. */
+export function inSite(store, locationId, site) {
+  return store.data.locations.some((l) => l.id === locationId && (l.site ?? DEFAULT_SITE) === site);
+}
+
+/** Batches stored in the locations of `site`, in store order. */
+export function batchesAt(store, site) {
+  const sites = new Map(store.data.locations.map((l) => [l.id, l.site ?? DEFAULT_SITE]));
+  return store.data.batches.filter((b) => (sites.get(b.location) ?? DEFAULT_SITE) === site);
+}
