diff --git a/tests/sites.test.js b/tests/sites.test.js
new file mode 100644
index 0000000..72009ae
--- /dev/null
+++ b/tests/sites.test.js
@@ -0,0 +1,36 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app } from "./helpers.js";
+
+const annex = { "X-Larder-Site": "annex" };
+
+test("an unknown site is a 400 unknown_site", async () => {
+  const { handle } = app();
+  const res = await handle({ path: "/items", headers: { "x-larder-site": "nowhere" } });
+  assert.equal(res.status, 400);
+  assert.equal(res.body.error.code, "unknown_site");
+});
+
+test("the annex sees only its own stock", async () => {
+  const { handle } = app();
+  const items = (await handle({ path: "/items", headers: annex })).body;
+  assert.equal(items.length, 6);
+  assert.ok(items.every((i) => i.onHand === 0));
+  assert.deepEqual((await handle({ path: "/batches", headers: annex })).body, []);
+  assert.equal((await handle({ path: "/batches/1", headers: annex })).status, 404);
+  assert.equal((await handle({ path: "/reports/stock-value", headers: annex })).body.totalCents, 0);
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", headers: annex, body: { portions: 1 } })).status, 409);
+  assert.deepEqual((await handle({ path: "/alerts", headers: annex })).body.expiring, []);
+});
+
+test("receiving at the annex, and stock-takes per site", async () => {
+  const { handle } = app();
+  const lots = [{ lot: "A-1", expires: null, location: "annex-fridge" }];
+  const wrong = await handle({ method: "POST", path: "/orders/2/receive", body: { lots: [lots[0], lots[0]] } });
+  assert.equal(wrong.body.error.code, "unknown_location");
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "annex-fridge" } })).status, 400);
+  const take = (await handle({ method: "POST", path: "/stocktakes", headers: annex, body: { location: "annex-fridge" } })).body;
+  assert.equal(take.location, "annex-fridge");
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 404);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish`, headers: annex })).status, 200);
+});
